def seed_initial_releases(apps, schema_editor):
    database = schema_editor.connection.alias
    Competitor = apps.get_model('competitive_vue_api', 'Competitor')
    CompetitorRelease = apps.get_model('competitive_vue_api', 'CompetitorRelease')
    Submission = apps.get_model('competitive_vue_api', 'Submission')
    CompetitorParameter = apps.get_model('competitive_vue_api', 'CompetitorParameter')

    for competitor in Competitor.objects.using(database).all().iterator():
        parameters = []
        for item in CompetitorParameter.objects.using(database).filter(
            competitor_id=competitor.id
        ).order_by('position', 'created_at'):
            text = (
                item.competitor_value.strip()
                if item.name.startswith('__text__:')
                else f'{item.name}：{item.competitor_value}'.strip('：')
            )
            if not text:
                continue
            parameters.append({
                'text': text,
                'ownValue': item.own_value,
                'comparisonStatus': item.comparison_status,
                'deviation': item.deviation,
            })
        release = CompetitorRelease.objects.using(database).create(
            competitor_id=competitor.id,
            number=1,
            brand=competitor.brand,
            name=competitor.name,
            model=competitor.model,
            regions=list(competitor.regions or []),
            price=competitor.price,
            dealer=competitor.dealer,
            advantage=competitor.advantage,
            weakness=competitor.weakness,
            tactic=competitor.tactic,
            parameters=parameters,
            changed_on=competitor.updated_on,
            expires_on=competitor.expires_on,
            status=competitor.status,
            note='由原正式竞品资料迁移生成。',
            created_by='系统迁移',
            is_current=True,
        )
        CompetitorRelease.objects.using(database).filter(id=release.id).update(
            created_at=competitor.created_at,
            updated_at=competitor.updated_at,
        )
        Submission.objects.using(database).filter(
            competitor_id=competitor.id
        ).update(competitor_release_id=release.id)


def remove_initial_releases(apps, schema_editor):
    database = schema_editor.connection.alias
    Submission = apps.get_model('competitive_vue_api', 'Submission')
    CompetitorRelease = apps.get_model('competitive_vue_api', 'CompetitorRelease')
    Submission.objects.using(database).update(competitor_release_id=None)
    CompetitorRelease.objects.using(database).all().delete()


